using System.Net;
using System.Net.Http.Headers;
using System.Net.Http.Json;
using System.Security.Cryptography;
using System.Security.Cryptography.X509Certificates;
using System.Text.Json;
using Azure.Identity;
using Microsoft.AspNetCore.DataProtection;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using OSI.Signal9.Server.Data;
using OSI.Signal9.Server.Keys;

namespace OSI.Signal9.API.Tests;

/// <summary>
/// Signing, encryption and Data Protection keys are generated by Signal9, stored in the database and wrapped by the
/// key-encryption key (ADR-0008).
/// </summary>
[TestClass]
public sealed class KeyStorageTests : IDisposable
{
    private readonly Signal9ApiFactory _factory = new();
    private readonly TestContext _testContext;

    public KeyStorageTests(TestContext testContext) => _testContext = testContext;

    private CancellationToken Ct => _testContext.CancellationToken;

    [TestMethod]
    public async Task Auth_signs_with_a_generated_RSA_3072_certificate_whose_NotBefore_is_its_activation()
    {
        var keys = await GetSigningKeysAsync(_factory.Auth);

        var key = keys.Single();
        Assert.AreEqual("RS256", key.GetProperty("alg").GetString());
        using var certificate = X509CertificateLoader.LoadCertificate(
            Convert.FromBase64String(key.GetProperty("x5c")[0].GetString()!));
        using var rsa = certificate.GetRSAPublicKey();
        Assert.AreEqual(3072, rsa!.KeySize);
        Assert.AreEqual(certificate.Subject, certificate.Issuer, "The certificate is self-signed.");
        Assert.AreEqual(_factory.Time.GetUtcNow().UtcDateTime, certificate.NotBefore.ToUniversalTime());
    }

    [TestMethod]
    public async Task A_fresh_auth_instance_sharing_the_database_uses_the_stored_keys()
    {
        var first = await GetSigningKeysAsync(_factory.Auth);
        await using var fresh = new Signal9AuthFactory(_factory.ConnectionString, _factory.Time);

        var second = await GetSigningKeysAsync(fresh);

        Assert.AreEqual(first.Single().GetProperty("kid").GetString(), second.Single().GetProperty("kid").GetString());
    }

    [TestMethod]
    public async Task Tokens_from_a_fresh_auth_instance_validate_on_api_with_the_stored_keys()
    {
        await _factory.SeedClientAsync("reporting-app", "tenants.read");
        await _factory.RequestTokenAsync("reporting-app", "tenants.read");
        await using var fresh = new Signal9AuthFactory(_factory.ConnectionString, _factory.Time);
        using var auth = fresh.CreateClient();
        var response = await auth.PostAsync("connect/token", Signal9ApiFactory.ClientCredentials("reporting-app", "tenants.read"), Ct);
        var token = (await response.Content.ReadFromJsonAsync<AccessToken>(Ct))!;

        using var api = _factory.CreateAnonymousClient();
        api.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", token.Value);

        Assert.AreEqual(HttpStatusCode.OK, (await api.GetAsync("api/v1/tenants", Ct)).StatusCode);
    }

    [TestMethod]
    public async Task A_host_with_another_key_encryption_key_cannot_read_the_stored_keys()
    {
        await GetSigningKeysAsync(_factory.Auth);
        await using var other = new Signal9AuthFactory(_factory.ConnectionString, _factory.Time, TestKeys.CreateKek());
        using var client = other.CreateClient();

        var response = await client.GetAsync(".well-known/jwks", Ct);

        Assert.AreEqual(HttpStatusCode.InternalServerError, response.StatusCode);
    }

    [TestMethod]
    public async Task A_cookie_protected_by_one_instance_is_readable_by_a_fresh_instance_sharing_the_database()
    {
        var cookie = Protector(_factory.Auth).Protect("session ticket");
        await using var fresh = new Signal9AuthFactory(_factory.ConnectionString, _factory.Time);

        Assert.AreEqual("session ticket", Protector(fresh).Unprotect(cookie));
    }

    [TestMethod]
    public async Task Data_protection_keys_are_wrapped_by_the_key_encryption_key()
    {
        var cookie = Protector(_factory.Auth).Protect("session ticket");
        await using var other = new Signal9AuthFactory(_factory.ConnectionString, _factory.Time, TestKeys.CreateKek());

        Assert.ThrowsExactly<CryptographicException>(() => Protector(other).Unprotect(cookie));
    }

    [TestMethod]
    public async Task A_host_that_cannot_read_the_data_protection_ring_fails_closed_instead_of_adding_its_own_key()
    {
        Protector(_factory.Auth).Protect("session ticket");
        await using var other = new Signal9AuthFactory(_factory.ConnectionString, _factory.Time, TestKeys.CreateKek());

        var refused = Assert.ThrowsExactly<CryptographicException>(() => Protector(other).Protect("session ticket"));
        Assert.IsInstanceOfType<InvalidOperationException>(refused.InnerException, "No default key, and none generated.");
        await using var scope = _factory.Auth.Services.CreateAsyncScope();
        Assert.AreEqual(1, await scope.ServiceProvider.GetRequiredService<Signal9DbContext>().DataProtectionKeys.CountAsync(Ct));
    }

    [TestMethod]
    public void The_key_encryption_key_provider_is_chosen_by_configuration()
    {
        using var certificate = Kek(new() { ["KeyEncryption:Provider"] = "Certificate", ["KeyEncryption:Certificate:Path"] = TestKeys.KekPath });
        using var keyVault = Kek(new() { ["KeyEncryption:Provider"] = "KeyVault", ["KeyEncryption:KeyVault:KeyId"] = "https://signal9.vault.azure.net/keys/kek" });

        Assert.IsInstanceOfType<CertificateKeyEncryptionKey>(certificate.Key);
        Assert.IsInstanceOfType<KeyVaultKeyEncryptionKey>(keyVault.Key);
    }

    [TestMethod]
    public void The_key_vault_hop_uses_managed_identity()
    {
        using var kek = Kek(new() { ["KeyEncryption:Provider"] = "KeyVault", ["KeyEncryption:KeyVault:KeyId"] = "https://signal9.vault.azure.net/keys/kek" });

        Assert.IsInstanceOfType<ManagedIdentityCredential>(((KeyVaultKeyEncryptionKey)kek.Key).Credential);
    }

    [TestMethod]
    [DataRow("https://attacker.example/keys/kek/1")]
    [DataRow("https://signal9.vault.azure.net/keys/other/1")]
    [DataRow("http://signal9.vault.azure.net/keys/kek/1")]
    public void Key_vault_never_unwraps_with_a_key_other_than_the_configured_one(string kekId)
    {
        using var kek = Kek(new() { ["KeyEncryption:Provider"] = "KeyVault", ["KeyEncryption:KeyVault:KeyId"] = "https://signal9.vault.azure.net/keys/kek" });

        Assert.ThrowsExactly<CryptographicException>(() =>
            kek.Key.Open(new SealedSecret(kekId, new byte[384], new byte[64]), "context"));
    }

    [TestMethod]
    public void A_key_encryption_certificate_below_RSA_3072_is_refused()
    {
        using var rsa = RSA.Create(2048);
        using var weak = new CertificateRequest("CN=weak", rsa, HashAlgorithmName.SHA256, RSASignaturePadding.Pkcs1)
            .CreateSelfSigned(DateTimeOffset.UtcNow.AddDays(-1), DateTimeOffset.UtcNow.AddDays(1));
        var path = Path.Combine(Path.GetTempPath(), $"signal9-weak-kek-{Guid.NewGuid():N}.pfx");
        File.WriteAllBytes(path, weak.Export(X509ContentType.Pfx));

        Assert.ThrowsExactly<InvalidOperationException>(() =>
        {
            using var kek = Kek(new() { ["KeyEncryption:Provider"] = "Certificate", ["KeyEncryption:Certificate:Path"] = path });
            _ = kek.Key;
        });
    }

    private async Task<JsonElement[]> GetSigningKeysAsync(Signal9AuthFactory auth)
    {
        using var client = auth.CreateClient();
        var jwks = await client.GetFromJsonAsync<JsonElement>(".well-known/jwks", Ct);
        return [.. jwks.GetProperty("keys").EnumerateArray()];
    }

    private static IDataProtector Protector(Signal9AuthFactory auth) =>
        auth.Services.GetRequiredService<IDataProtectionProvider>().CreateProtector("KeyStorageTests");

    private static KekHost Kek(Dictionary<string, string?> settings)
    {
        var configuration = new ConfigurationBuilder().AddInMemoryCollection(settings).Build();
        var services = new ServiceCollection().AddSignal9KeyEncryption(configuration).BuildServiceProvider();
        return new KekHost(services);
    }

    private sealed class KekHost(ServiceProvider services) : IDisposable
    {
        public KeyEncryptionKey Key => services.GetRequiredService<KeyEncryptionKey>();

        public void Dispose() => services.Dispose();
    }

    public void Dispose() => _factory.Dispose();
}
